/* Minimal devbridgeAutocomplete-compatible shim for preview-recon.
   The real preview.exe bundled devbridge-autocomplete; this reconstruction
   reimplements only the surface utils.js exercises: a lookup-driven dropdown
   with keyboard navigation (Up/Down/Enter) and mouse selection. */
(function ($) {
    $.fn.devbridgeAutocomplete = function (options) {
        return this.each(function () {
            var input = $(this);
            var wrap = $(options.appendTo || 'body');
            var ul = $('<ul class="autocomplete-suggestions"></ul>')
                .css({
                    position: 'absolute', zIndex: 99999,
                    maxHeight: (options.maxHeight || 230) + 'px', overflow: 'auto',
                    background: '#fff', border: '1px solid #ccc',
                    listStyle: 'none', margin: 0, padding: 0, minWidth: 200
                })
                .appendTo(wrap)
                .hide();

            var items = [];   // loaded suggestions only; fetched in pages of 20
            var lis = [];
            var active = -1;
            var timer = null;
            var query = '';
            var offset = 0;
            var hasMore = false;
            var loading = false;

            function hide() {
                ul.hide().empty();
                items = []; lis = []; active = -1;
                offset = 0; hasMore = false;
            }

            function paint() {
                lis.forEach(function (li, i) {
                    if (i === active) li.addClass('autocomplete-selected');
                    else li.removeClass('autocomplete-selected');
                });
            }

            function choose(i) {
                var s = items[i];
                if (!s) return;
                input.val(s.value);
                hide();
                options.onSelect && options.onSelect(s);
            }

            function render(reset) {
                if (reset) {
                    ul.empty();
                    lis = [];
                }
                for (var i = lis.length; i < items.length; i++) {
                    (function (index) {
                        var s = items[index];
                        var li = $('<li class="autocomplete-suggestion"></li>')
                            .text(s.value)
                            .appendTo(ul);
                        li.on('mouseenter', function () { active = index; paint(); });
                        li.on('mousedown', function (e) { e.preventDefault(); choose(index); });
                        lis.push(li);
                    })(i);
                }
                if (!items.length && options.showNoSuggestionNotice && options.noSuggestionNotice) {
                    $('<li class="autocomplete-no-suggestion"></li>')
                        .text(options.noSuggestionNotice).appendTo(ul);
                }
                paint();
                ul.show();
            }

            function fetch(q, append) {
                if (loading) return;
                loading = true;
                options.lookup(q, function (resp) {
                    var page = (resp && resp.suggestions) || [];
                    if (!append) {
                        items = [];
                        offset = 0;
                        active = -1;
                    }
                    items = items.concat(page);
                    offset = items.length;
                    hasMore = !!(resp && resp.hasMore);
                    loading = false;
                    render(!append);
                }, append ? offset : 0);
            }

            ul.on('scroll', function () {
                if (hasMore && !loading && this.scrollTop + this.clientHeight >= this.scrollHeight - 40) {
                    fetch(query, true);
                }
            });

            input.on('focus', function () {
                if (!input.val() && !items.length) {
                    query = '';
                    fetch('', false);
                }
            });

            input.on('input keyup', function (e) {
                if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Enter') return;
                query = input.val();
                clearTimeout(timer);
                if (!query || query.length < (options.minChars || 1)) { hide(); return; }
                timer = setTimeout(function () { fetch(query, false); }, 80);
            });

            input.on('keydown', function (e) {
                if (e.key === 'Escape') { hide(); return; }
                if (!items.length) return;
                if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    active = (active + 1) % items.length;
                    paint();
                } else if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    active = (active - 1 + items.length) % items.length;
                    paint();
                } else if (e.key === 'Enter') {
                    e.preventDefault();
                    choose(active >= 0 ? active : 0);
                }
            });

            input.on('blur', function () { setTimeout(hide, 150); });
        });
    };
})(jQuery);